use std::fs

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if x == k { return true }
            if x < k { cur = self.lefts[cur as usize] } else { cur = self.rights[cur as usize] }
        }
        false
    }

    fn insert(self, x: int) -> bool {
        if self.root < 0 {
            self.keys.push(x)
            self.lefts.push(-1)
            self.rights.push(-1)
            self.root = 0
            return true
        }
        let mut cur = self.root
        loop {
            let k = self.keys[cur as usize]
            if x == k { return false }
            let idx: int = self.keys.len() as int
            if x < k {
                let l = self.lefts[cur as usize]
                if l < 0 {
                    self.lefts[cur as usize] = idx
                    break
                }
                cur = l
            } else {
                let r = self.rights[cur as usize]
                if r < 0 {
                    self.rights[cur as usize] = idx
                    break
                }
                cur = r
            }
        }
        self.keys.push(x)
        self.lefts.push(-1)
        self.rights.push(-1)
        true
    }

    fn set_child(self, parent: int, node: int, child: int) {
        if parent < 0 {
            self.root = child
        } else if self.lefts[parent as usize] == node {
            self.lefts[parent as usize] = child
        } else {
            self.rights[parent as usize] = child
        }
    }

    fn delete(self, x: int) -> bool {
        let mut parent = -1
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if x == k { break }
            parent = cur
            if x < k { cur = self.lefts[cur as usize] } else { cur = self.rights[cur as usize] }
        }
        if cur < 0 { return false }
        let l = self.lefts[cur as usize]
        let r = self.rights[cur as usize]
        if l >= 0 && r >= 0 {
            let mut sp = cur
            let mut s = r
            while self.lefts[s as usize] >= 0 {
                sp = s
                s = self.lefts[s as usize]
            }
            self.keys[cur as usize] = self.keys[s as usize]
            let sr = self.rights[s as usize]
            self.set_child(sp, s, sr)
        } else if l >= 0 {
            self.set_child(parent, cur, l)
        } else {
            self.set_child(parent, cur, r)
        }
        true
    }

    fn height_of(self, i: int) -> int {
        if i < 0 { return 0 }
        let a = self.height_of(self.lefts[i as usize])
        let b = self.height_of(self.rights[i as usize])
        if a > b { a + 1 } else { b + 1 }
    }

    fn inorder(self) -> string {
        let mut out = ""
        let mut stack: Vec<int> = []
        let mut cur = self.root
        let mut first = true
        while cur >= 0 || stack.len() > 0 {
            while cur >= 0 {
                stack.push(cur)
                cur = self.lefts[cur as usize]
            }
            let n = stack.pop().unwrap_or(0)
            if !first { out = out + " " }
            first = false
            out = out + "${self.keys[n as usize]}"
            cur = self.rights[n as usize]
        }
        if first { return "<empty>" }
        out
    }

    fn min(self) -> string {
        if self.root < 0 { return "empty" }
        let mut cur = self.root
        while self.lefts[cur as usize] >= 0 { cur = self.lefts[cur as usize] }
        "${self.keys[cur as usize]}"
    }

    fn max(self) -> string {
        if self.root < 0 { return "empty" }
        let mut cur = self.root
        while self.rights[cur as usize] >= 0 { cur = self.rights[cur as usize] }
        "${self.keys[cur as usize]}"
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], lefts: [], rights: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").collect()
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.insert(x) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.delete(x) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            println(t.inorder())
        } else if cmd == "height" {
            println("${t.height_of(t.root)}")
        } else if cmd == "min" {
            println(t.min())
        } else if cmd == "max" {
            println(t.max())
        }
    }
}

